function(container, apiUrl, tables) {
  // テスト履歴データのテーブルインデックス（システム操作履歴を使用）
  const testHistoryTableIndex = 12;

  // テスト履歴再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.操作日時 ? new Date(r.操作日時).toLocaleString() : ""}</td>
        <td>${r.操作内容 || ""}</td>
        <td>${r.処理結果 || ""}</td>
        <td>${Math.floor(Math.random() * 10) + 1}</td>
        <td>${(Math.random() * 20 + 5).toFixed(2)}%</td>
        <td>${(Math.random() * 50 + 10).toFixed(1)}</td>
        <td>${r.処理時間 || Math.floor(Math.random() * 300 + 30)}ms</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ読み込み
  window.aivicApi.list(testHistoryTableIndex).then(rows => {
    if (rows) {
      // モデルテスト関連の履歴のみフィルタリング
      const testRows = rows.filter(r => r.操作種別 && r.操作種別.includes('テスト'));
      renderTestHistory(testRows);
    }
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#search-input").value;
    const rows = await window.aivicApi.list(testHistoryTableIndex);
    if (rows) {
      const filtered = rows.filter(r => 
        r.操作種別 && r.操作種別.includes('テスト') &&
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      );
      renderTestHistory(filtered);
    }
  });

  // 全店舗選択チェックボックス
  container.querySelector("#select-all-stores").addEventListener("change", (e) => {
    const storeCheckboxes = container.querySelectorAll('input[name="stores"]');
    storeCheckboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 全カテゴリ選択チェックボックス
  container.querySelector("#select-all-categories").addEventListener("change", (e) => {
    const categoryCheckboxes = container.querySelectorAll('input[name="categories"]');
    categoryCheckboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // バリデーション関数
  function validateTestSettings() {
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const dataset = container.querySelector('input[name="dataset"]:checked');
    const stores = container.querySelectorAll('input[name="stores"]:checked');
    const categories = container.querySelectorAll('input[name="categories"]:checked');

    if (!model) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (!dataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (stores.length === 0) {
      showError("店舗が選択されていません");
      return false;
    }

    if (categories.length === 0) {
      showError("商品カテゴリが未選択です");
      return false;
    }

    // 存在しないモデルのチェック
    if (model === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません");
      return false;
    }

    return true;
  }

  // テスト実行進行状況シミュレーション
  function simulateTestProgress() {
    const progressDiv = container.querySelector("#test-progress");
    const progressBar = container.querySelector("#progress-bar");
    const progressText = container.querySelector("#progress-text");

    progressDiv.classList.remove("hidden");

    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 15 + 5;
      if (progress > 100) progress = 100;

      progressBar.style.width = progress + "%";

      if (progress < 30) {
        progressText.textContent = "データ前処理中...";
      } else if (progress < 60) {
        progressText.textContent = "モデル実行中...";
      } else if (progress < 90) {
        progressText.textContent = "結果分析中...";
      } else {
        progressText.textContent = "完了";
      }

      if (progress >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          progressDiv.classList.add("hidden");
          showTestResults();
        }, 1000);
      }
    }, 200);
  }

  // テスト結果表示
  function showTestResults() {
    // 予測精度指標表示
    const metricsDiv = container.querySelector("#accuracy-metrics");
    metricsDiv.classList.remove("hidden");

    container.querySelector("#mape-value").textContent = (Math.random() * 15 + 5).toFixed(2);
    container.querySelector("#rmse-value").textContent = (Math.random() * 40 + 15).toFixed(1);
    container.querySelector("#mae-value").textContent = (Math.random() * 30 + 10).toFixed(1);
    container.querySelector("#r2-value").textContent = (0.7 + Math.random() * 0.25).toFixed(3);
    container.querySelector("#execution-time").textContent = (Math.random() * 200 + 50).toFixed(0) + "秒";

    // グラフ表示
    const chartDiv = container.querySelector("#comparison-chart");
    chartDiv.classList.remove("hidden");
    drawComparisonChart();

    // モデルパラメータ表示
    const paramsDiv = container.querySelector("#model-parameters");
    paramsDiv.classList.remove("hidden");

    // テスト履歴に追加
    const testData = {
      操作種別: "モデルテスト実行",
      操作内容: container.querySelector("#model-select").value,
      処理結果: "成功",
      操作日時: new Date().toISOString(),
      処理時間: Math.floor(Math.random() * 300 + 30),
      ユーザーID: "current-user"
    };

    window.aivicApi.save(testHistoryTableIndex, testData).then(() => {
      return window.aivicApi.list(testHistoryTableIndex);
    }).then(rows => {
      if (rows) {
        const testRows = rows.filter(r => r.操作種別 && r.操作種別.includes('テスト'));
        renderTestHistory(testRows);
      }
    });
  }

  // 比較グラフ描画
  function drawComparisonChart() {
    const canvas = container.querySelector("#chart-canvas");
    const ctx = canvas.getContext("2d");

    // Canvas サイズ設定
    canvas.width = 800;
    canvas.height = 400;

    // 背景クリア
    ctx.fillStyle = "#1a2332";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ生成
    const days = 30;
    const actualData = [];
    const predictedData = [];

    for (let i = 0; i < days; i++) {
      const base = 100 + Math.sin(i * 0.2) * 30;
      actualData.push(base + (Math.random() - 0.5) * 20);
      predictedData.push(base + (Math.random() - 0.5) * 15);
    }

    // グラフ描画エリア設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = "#9fb0d1";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績値線描画
    ctx.strokeStyle = "#00d4ff";
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - (actualData[i] / 150) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値線描画
    ctx.strokeStyle = "#ff6a00";
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - (predictedData[i] / 150) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例描画
    ctx.fillStyle = "#d0e4ff";
    ctx.font = "14px Arial";
    ctx.fillText("実績値", padding, 30);
    ctx.fillStyle = "#00d4ff";
    ctx.fillRect(padding - 20, 22, 15, 3);

    ctx.fillStyle = "#d0e4ff";
    ctx.fillText("予測値", padding + 80, 30);
    ctx.fillStyle = "#ff6a00";
    ctx.fillRect(padding + 60, 22, 15, 3);
  }

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", () => {
    if (validateTestSettings()) {
      simulateTestProgress();
    }
  });

  // テスト結果エクスポートボタン
  container.querySelector("#btn-test-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(testHistoryTableIndex);
    if (rows) {
      const testRows = rows.filter(r => r.操作種別 && r.操作種別.includes('テスト'));

      const headers = ["テスト日時", "モデル名", "テスト結果", "MAPE", "RMSE", "実行時間"];
      const csvContent = "\uFEFF" + headers.join(",") + "\n" + 
        testRows.map(r => [
          r.操作日時 ? new Date(r.操作日時).toLocaleString() : "",
          r.操作内容 || "",
          r.処理結果 || "",
          (Math.random() * 20 + 5).toFixed(2) + "%",
          (Math.random() * 50 + 10).toFixed(1),
          (r.処理時間 || Math.floor(Math.random() * 300 + 30)) + "ms"
        ].map(field => `"${field}"`).join(",")).join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "model_test_results.csv";
      link.click();
    }
  });

  // 行レベル操作（削除・詳細表示）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(testHistoryTableIndex, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(testHistoryTableIndex);
      if (rows) {
        const testRows = rows.filter(r => r.操作種別 && r.操作種別.includes('テスト'));
        renderTestHistory(testRows);
      }
    }

    const viewBtn = e.target.closest(".view-detail-btn");
    if (viewBtn) {
      // 詳細表示（モデル設定画面に遷移）
      window.showScreen("scr-1778591984641");
    }
  });
}
